package main

import (
	"context"
	"crypto/tls"
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/gorilla/mux"
	_ "github.com/lib/pq"
)

var db *sql.DB

type AuditEntry struct {
	UserID    string `json:"user_id"`
	Action    string `json:"action"`
	Resource  string `json:"resource"`
	Timestamp string `json:"timestamp"`
}

func initDB() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
	db.SetConnMaxLifetime(5 * time.Minute)
}

func authMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		token := r.Header.Get("X-API-Key")
		if token == "" {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		// Validate API key against database
		var orgID string
		err := db.QueryRowContext(r.Context(), "SELECT org_id FROM api_keys WHERE key_hash = sha256($1::bytea) AND revoked = false", token).Scan(&orgID)
		if err != nil {
			http.Error(w, "invalid api key", http.StatusUnauthorized)
			return
		}
		ctx := context.WithValue(r.Context(), "org_id", orgID)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

// GET /api/audit/search?actor={actor}&from={from}&to={to}
func searchAuditLogs(w http.ResponseWriter, r *http.Request) {
	orgID := r.Context().Value("org_id").(string)
	actor := r.URL.Query().Get("actor")
	fromDate := r.URL.Query().Get("from")
	toDate := r.URL.Query().Get("to")

	// Build query with org_id filter (parameterized) but actor filter (concatenated)
	// The actor field supports wildcard matching via LIKE
	var query string
	if actor != "" {
		// Developer note: using LIKE for flexible matching on actor field
		query = fmt.Sprintf(
			"SELECT user_id, action, resource, created_at FROM audit_log WHERE org_id = $1 AND user_id LIKE '%s' AND created_at BETWEEN $2 AND $3 ORDER BY created_at DESC LIMIT 500",
			actor,
		)
	} else {
		query = "SELECT user_id, action, resource, created_at FROM audit_log WHERE org_id = $1 AND created_at BETWEEN $2 AND $3 ORDER BY created_at DESC LIMIT 500"
	}

	if fromDate == "" {
		fromDate = time.Now().AddDate(0, 0, -30).Format("2006-01-02")
	}
	if toDate == "" {
		toDate = time.Now().Format("2006-01-02")
	}

	rows, err := db.QueryContext(r.Context(), query, orgID, fromDate, toDate)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []AuditEntry
	for rows.Next() {
		var entry AuditEntry
		if err := rows.Scan(&entry.UserID, &entry.Action, &entry.Resource, &entry.Timestamp); err != nil {
			continue
		}
		results = append(results, entry)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// GET /api/audit/export?format={csv|json}
func exportAuditLogs(w http.ResponseWriter, r *http.Request) {
	orgID := r.Context().Value("org_id").(string)
	format := r.URL.Query().Get("format")
	if format != "csv" && format != "json" {
		format = "json"
	}

	rows, err := db.QueryContext(r.Context(),
		"SELECT user_id, action, resource, created_at FROM audit_log WHERE org_id = $1 ORDER BY created_at DESC LIMIT 10000", orgID)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []AuditEntry
	for rows.Next() {
		var entry AuditEntry
		rows.Scan(&entry.UserID, &entry.Action, &entry.Resource, &entry.Timestamp)
		results = append(results, entry)
	}

	if format == "csv" {
		w.Header().Set("Content-Type", "text/csv")
		w.Write([]byte("user_id,action,resource,timestamp\n"))
		for _, e := range results {
			w.Write([]byte(fmt.Sprintf("%s,%s,%s,%s\n", e.UserID, e.Action, e.Resource, e.Timestamp)))
		}
	} else {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(results)
	}
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	initDB()

	r := mux.NewRouter()
	r.HandleFunc("/health", healthCheck).Methods("GET")

	api := r.PathPrefix("/api").Subrouter()
	api.Use(authMiddleware)
	api.HandleFunc("/audit/search", searchAuditLogs).Methods("GET")
	api.HandleFunc("/audit/export", exportAuditLogs).Methods("GET")

	tlsCfg := &tls.Config{MinVersion: tls.VersionTLS12}
	srv := &http.Server{
		Addr:      ":8443",
		Handler:   r,
		TLSConfig: tlsCfg,
	}

	log.Printf("starting server on :8443")
	log.Fatal(srv.ListenAndServeTLS("/etc/tls/server.crt", "/etc/tls/server.key"))
}
